// Início screen: four-step guide that checks itself, the Visão geral capture with the chosen step
// highlighted, and a card per interface area. Shown on open until the steps are done or the user
// checks "Não mostrar mais o guia"; afterwards it stays in Início and Ajuda.

import { brandLogo } from "../brand.mjs";
import { installLerd } from "../lerd-setup.mjs";
import { get, put } from "../api.mjs";
import { esc, icon, reportError } from "../dom.mjs";
import { t } from "../i18n.mjs";

// highlights over img/manual/visao-geral.png (percentages of the capture generated by scripts/manual_shots.sh)
export const SPOTS = {
  lerd: { box: [73.6, 1.0, 16.7, 3.0], text: t("O estado do Lerd fica no alto, à direita: verde quando nginx, DNS .test e PHP respondem. O item Lerd da barra lateral leva à tela dele.") },
  projetos: { box: [19.1, 7.3, 49.6, 30.0], text: t("Sites PHP do Lerd e projetos Node aparecem na Visão geral. Clique num deles para abrir a página do projeto.") },
  agentes: { box: [0.5, 35.4, 16.1, 19.0], text: t("Sessões dos agentes, prompts, uso e custo, branches e histórico ficam no grupo Agentes da barra lateral.") },
  terminal: { box: [17.4, 69.0, 82.6, 31.0], text: t("O painel de terminal fica embaixo (⌘J mostra ou esconde). ⌘T abre um terminal novo na pasta escolhida.") },
  organizar: { box: [70.0, 7.3, 28.3, 11.0], text: t("Tarefas abertas aparecem na Visão geral. Tarefas, post-its, tags e índice ficam no grupo Organizar da barra lateral.") },
};

export const AREAS = [
  { id: "projetos", icon: "globe", title: t("Projetos"), text: t("Sites PHP do Lerd e projetos Node: abrir, ligar o servidor, ver logs e a depuração."), go: "#/overview" },
  { id: "terminal", icon: "terminal", title: t("Terminais"), text: t("Um terminal por projeto, com tarefas e notas que viram memória em Markdown."), go: "#/terminals" },
  { id: "lerd", icon: "database", title: "Lerd", text: t("PHP, nginx, banco e HTTPS local dos sites. Ligar, parar e ver o que está rodando."), go: "#/lerd" },
  { id: "agentes", icon: "spark", title: t("Agentes"), text: t("Sessões do Claude Code e do Codex lidas do disco, com custo estimado e branches."), go: "#/agentes" },
  { id: "agentes", icon: "text", title: "Prompts", text: t("Instruções prontas preenchidas com a sessão atual, para mandar ao agente."), go: "#/prompts" },
  { id: "organizar", icon: "check-square", title: t("Organizar"), text: t("Tarefas, post-its, tags e o índice de tudo o que foi feito em cada projeto."), go: "#/tasks" },
];

export class HomeView {
  constructor(root, options) {
    this.root = root;
    this.options = options;
    this.spot = null;
    this.root.addEventListener("click", (e) => this.onClick(e));
    this.root.addEventListener("keydown", (e) => this.onKey(e));
    this.root.innerHTML = `<div class="loading"><span class="skeleton w-40"></span><span class="skeleton w-70"></span></div>`;
    this.load();
  }

  async load() {
    try {
      this.guide = await get("/api/guide");
      if (!this.spot) {
        const next = this.guide.steps.find((s) => !s.ok);
        this.spot = next ? next.id : "projetos";
      }
      this.render();
      // the agent index is still on its first read: check again shortly (up to 40 times)
      if (this.guide.steps.some((st) => st.lendo) && (this.retries = (this.retries || 0) + 1) <= 40) {
        this.timer = setTimeout(() => this.load(), 500);
      }
    } catch (err) {
      reportError(err);
    }
  }

  destroy() {
    clearTimeout(this.timer);
  }

  greeting() {
    const h = new Date().getHours();
    return h < 12 ? t("Bom dia") : h < 18 ? t("Boa tarde") : t("Boa noite");
  }

  render() {
    const g = this.guide;
    const missing = g.steps.filter((s) => !s.ok && !s.optional).length;
    const head = g.done ? t("Tudo pronto. Os passos essenciais estão feitos.")
      : missing === 1 ? t("Falta 1 passo para tudo funcionar.") : t("Faltam {n} passos para tudo funcionar.", { n: missing });
    const spot = SPOTS[this.spot] || SPOTS.projetos;
    const [x, y, w, h] = spot.box;
    const action = {
      lerd: this.lerdActions(g.steps.find((s) => s.id === "lerd")),
      projetos: `<button class="btn btn-sm" data-go="#/node">${icon("plus")}<span>${t("Adicionar")}</span></button>`,
      agentes: `<button class="btn btn-sm" data-go="#/agentes">${icon("spark")}<span>${t("Ver agentes")}</span></button>`,
      terminal: `<button class="btn btn-primary btn-sm" data-home="terminal">${icon("terminal")}<span>${t("Abrir terminal")}</span></button>`,
    };
    this.root.innerHTML = `<div class="page in-page">
        ${brandLogo()}
      <div class="in-hello">
        <div class="in-left">
          <h1>${this.greeting()}. ${esc(head)}</h1>
          <p class="dim">${g.done ? t("O guia sai da abertura do app. Ele continua aqui e em Ajuda.") : t("O guia confere sozinho o que já está pronto e some da abertura quando terminar.")}</p>
          <label class="in-dismiss"><input type="checkbox" data-home="dismiss" ${g.skipped ? "checked" : ""}>
            <span>${t("Não mostrar mais o guia")} <span class="dim">${t("(o app abre na Visão geral; o guia continua em Início e em Ajuda)")}</span></span></label>
          <ol class="in-steps">${g.steps.map((s, i) => `<li class="in-step ${s.ok ? "is-done" : ""} ${s.id === this.spot ? "is-on" : ""}" data-spot="${s.id}" tabindex="0">
            <span class="in-ck" aria-hidden="true">${s.ok ? icon("check") : i + 1}</span>
            <span class="in-step-main"><b>${esc(s.title)}</b><span class="dim">${esc(s.detail)}</span></span>
            ${s.ok ? `<span class="sr-only">${t("feito")}</span>` : action[s.id] || ""}</li>`).join("")}</ol>
        </div>
        <figure class="in-shot">
          <div class="in-shot-frame"><img src="img/manual/visao-geral.png" alt="${t("Captura da Visão geral do Vulcan Celox com a área do passo escolhido destacada")}">
            <span class="in-hl" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%"></span></div>
          <figcaption>${esc(spot.text)}</figcaption>
        </figure>
      </div>
      <h2 class="in-sub">${t("O que cada parte faz")}</h2>
      <div class="in-areas">${AREAS.map((a) => `<a class="in-area" href="${a.go}" data-spot-hover="${a.id}">
          <span class="in-ic">${icon(a.icon)}</span><b>${esc(a.title)}</b><span class="dim">${esc(a.text)}</span></a>`).join("")}</div>
      <p class="dim in-help">${t("Dúvidas? Abra {link} (⌘?) ou use o botão ? no alto de cada tela.", { link: `<a href="#/ajuda" data-go="#/ajuda">${t("Ajuda")}</a>` })}</p>
    </div>`;
  }

  lerdActions(step) {
    if (!step) return "";
    if (step.skipped) return `<button class="btn btn-ghost btn-sm" data-home="lerd-use">${t("Usar o Lerd")}</button>`;
    const skip = `<button class="btn btn-ghost btn-sm" data-home="lerd-skip">${t("Não uso")}</button>`;
    if (step.state === "absent") return `<button class="btn btn-sm" data-home="lerd-install">${icon("plus")}<span>${t("Instalar")}</span></button>${skip}`;
    return `<button class="btn btn-sm" data-service="start">${icon("play")}<span>${t("Ligar")}</span></button>${skip}`;
  }

  // the step has tabindex, so it responds to Enter and Space like a click
  onKey(event) {
    if (event.key !== "Enter" && event.key !== " ") return;
    const step = event.target.closest && event.target.closest("[data-spot]");
    if (!step || event.target !== step) return;  // a button or link inside the step keeps its own behavior
    event.preventDefault();
    this.pick(step.dataset.spot, true);
  }

  // redraws with the chosen step and, if focus was on it, returns focus to the new step
  pick(spot, keepFocus) {
    this.spot = spot;
    this.render();
    if (keepFocus) {
      const again = this.root.querySelector(`[data-spot="${CSS.escape(spot)}"]`);
      if (again) again.focus();
    }
  }

  async onClick(event) {
    const step = event.target.closest("[data-spot]");
    const btn = event.target.closest("[data-home]");
    try {
      if (btn && btn.dataset.home === "dismiss") {
        this.guide = await put("/api/guide", { skipped: btn.checked });
        return this.render();
      }
      if (btn && btn.dataset.home === "lerd-install") return installLerd();
      if (btn && (btn.dataset.home === "lerd-skip" || btn.dataset.home === "lerd-use")) {
        this.guide = await put("/api/guide", { lerd_skipped: btn.dataset.home === "lerd-skip" });
        return this.render();
      }
      if (btn && btn.dataset.home === "terminal") {
        if (window.vulcanCommand) await window.vulcanCommand("newTerminal");
        return setTimeout(() => this.load(), 1500);
      }
      if (step && !event.target.closest("button")) this.pick(step.dataset.spot, step.contains(document.activeElement));
    } catch (err) {
      reportError(err);
    }
    return null;
  }
}
